function commit(cells:Cells,width=project.value!.width,height=project.value!.height){const p=project.value;if(!p||layer.value?.locked)return;if(width===p.width&&height===p.height&&!cells.some((c,i)=>c!==p.cells[i]))return;history.value=[...history.value.slice(-39),snapshot()];future.value=[];store.update({...p,width,height,cells,layers:[{...p.layers[0],cells}]});selected.value=null;reduced.value=null;focused.value=-1;widthDraft.value=width;heightDraft.value=height}
type PhotoState={crop:Crop;rotation:number;type:'cartoon'|'photo'|null;width:number;colors:number;style:'cartoon'|'realistic';background:boolean;allowedMode:boolean;allowed:string[];ratio:'free'|'square'}
const photoUndo=ref<PhotoState[]>([]),photoRedo=ref<PhotoState[]>([]),photoBaseline=ref<PhotoState|null>(null)
let restoringPhoto=false,lastPhotoChange=0
function photoState():PhotoState{return {crop:{...crop.value},rotation:rotation.value,type:imageType.value,width:targetWidth.value,colors:maxColors.value,style:style.value,background:removeBackground.value,allowedMode:allowedMode.value,allowed:[...allowed.value],ratio:cropRatio.value}}
function resetPhotoHistory(){photoUndo.value=[];photoRedo.value=[];photoBaseline.value=photoState();lastPhotoChange=0}
function restorePhoto(s:PhotoState){restoringPhoto=true;crop.value={...s.crop};rotation.value=s.rotation;imageType.value=s.type;targetWidth.value=s.width;maxColors.value=s.colors;style.value=s.style;removeBackground.value=s.background;allowedMode.value=s.allowedMode;allowed.value=[...s.allowed];cropRatio.value=s.ratio;restoringPhoto=false;lastPhotoChange=0}
watch(photoState,(now,old)=>{if(restoringPhoto||mode.value!=='import'||importStage.value!=='photo')return;const time=Date.now();if(time-lastPhotoChange>300)photoUndo.value.push(old);lastPhotoChange=time;photoRedo.value=[]},{deep:true,flush:'sync'})
function photoChanged(id:string){const b=photoBaseline.value;if(!b)return false;const s=photoState();return id==='size'?JSON.stringify(s.crop)!==JSON.stringify(b.crop):id==='rotate'?s.rotation!==b.rotation:id==='detail'?s.width!==b.width:id==='colors'?s.colors!==b.colors:id==='style'?s.type!==b.type:id==='background'?s.background!==b.background:id==='palette'?s.allowedMode!==b.allowedMode||JSON.stringify(s.allowed)!==JSON.stringify(b.allowed):false}
function setCropRatio(value:'free'|'square'){cropRatio.value=value;if(value==='square'&&image.value){const ratio=rotation.value%180?image.value.naturalHeight/image.value.naturalWidth:image.value.naturalWidth/image.value.naturalHeight,c=crop.value,width=Math.min(c.width,c.height/ratio);crop.value={x:c.x+(c.width-width)/2,y:c.y+(c.height-width*ratio)/2,width,height:width*ratio}}}
function undo(){if(busy.value)return;if(mode.value==='recolor'){const previous=recolorUndo.value.pop();if(previous){recolorRedo.value.push(targetColor.value);targetColor.value=previous;compareOriginal.value=false}return;}if(mode.value==='import'&&importStage.value==='photo'){const previous=photoUndo.value.pop();if(previous){photoRedo.value.push(photoState());restorePhoto(previous)}return;}if(mode.value==='import'&&candidate.value){if(!modeUndo.value.length)return;modeRedo.value=[...modeRedo.value,[...candidate.value.cells]];candidate.value={...candidate.value,cells:modeUndo.value.at(-1)!};modeUndo.value=modeUndo.value.slice(0,-1);return}if(mode.value){if(!modeUndo.value.length)return;modeRedo.value=[...modeRedo.value,[...(modeCells.value||project.value!.cells)]];modeCells.value=modeUndo.value.at(-1)!;modeUndo.value=modeUndo.value.slice(0,-1);return}if(!history.value.length||busy.value||layer.value?.locked)return;future.value=[...future.value,snapshot()];const p=history.value[history.value.length-1]!;history.value=history.value.slice(0,-1);store.update({...project.value!,width:p.width,height:p.height,cells:p.cells,layers:p.layers});clearTransient()}
function redo(){if(busy.value)return;if(mode.value==='recolor'){const next=recolorRedo.value.pop();if(next){recolorUndo.value.push(targetColor.value);targetColor.value=next;compareOriginal.value=false}return;}if(mode.value==='import'&&importStage.value==='photo'){const next=photoRedo.value.pop();if(next){photoUndo.value.push(photoState());restorePhoto(next)}return;}if(mode.value==='import'&&candidate.value){if(!modeRedo.value.length)return;modeUndo.value=[...modeUndo.value,[...candidate.value.cells]];candidate.value={...candidate.value,cells:modeRedo.value.at(-1)!};modeRedo.value=modeRedo.value.slice(0,-1);return}if(mode.value){if(!modeRedo.value.length)return;modeUndo.value=[...modeUndo.value,[...(modeCells.value||project.value!.cells)]];modeCells.value=modeRedo.value.at(-1)!;modeRedo.value=modeRedo.value.slice(0,-1);return}if(!future.value.length||busy.value||layer.value?.locked)return;history.value=[...history.value,snapshot()];const p=future.value[future.value.length-1]!;future.value=future.value.slice(0,-1);store.update({...project.value!,width:p.width,height:p.height,cells:p.cells,layers:p.layers});clearTransient()}
