function activate(next:Tool){if(['pencil','fill','eraser','recolor','select'].includes(next)){enterMode(next);return}exitMode();board.value?.cancel();panel.value='';reduced.value=null;focused.value=-1;placing.value=false;placement.value=null;tool.value=next;if(next!=='select')selected.value=null}
function pick(code:string){showToast(`已选取 ${code} · ${colorByCode(code)?.name||''}`);if(mode.value==='recolor'){targetColor.value=code;recolorStep.value='target';tool.value='pan'}else{chooseColor(code);tool.value=mode.value==='fill'?'fill':'pencil'}}
function openPanel(next:string){board.value?.cancel();if(placing.value){placing.value=false;placement.value=null;tool.value='pan'}if(['generate','reduce'].includes(next))selected.value=null;reduced.value=null;compareOriginal.value=false;panel.value=panel.value===next?'':next;expanded.value=false;if(next==='colors'&&!usage.value.length)paletteTab.value='all';if(next==='generate'&&image.value)scheduleGeneration()}
