function clearTransient(){closePanel();selected.value=null;placing.value=false;placement.value=null;focused.value=-1;widthDraft.value=project.value!.width;heightDraft.value=project.value!.height}
function focus(index:number){if(!project.value?.cells[index])return;recolorUndo.value=[];recolorRedo.value=[];compareOriginal.value=false;focused.value=index;targetColor.value=project.value.cells[index]!;recolorStep.value='target';tool.value='recolor'}
function applyRecolor(){const cells=[...project.value!.cells],count=recolorIndices.value.length;recolorIndices.value.forEach(i=>cells[i]=targetColor.value);commit(cells);closePanel();showToast(`已替换 ${count} 颗拼豆`)}
function startReduction(){try{reduced.value=reduceColors(project.value!.cells,reduceLimit.value,protectedCodes.value);compareOriginal.value=false}catch(e){showToast((e as Error).message)}}
function toggleProtected(code:string){reduced.value=null;protectedCodes.value=protectedCodes.value.includes(code)?protectedCodes.value.filter(c=>c!==code):[...protectedCodes.value,code]}
function copySelection(move=false){if(!selected.value)return;clipboard.value={rect:{...selected.value},cells:rectIndices(selected.value,project.value!.width).map(i=>(modeCells.value||project.value!.cells)[i])};moving.value=move;placing.value=true;placement.value=null;tool.value='paste'}
const placementCells=computed(()=>{if(!placing.value||!placement.value||!clipboard.value)return null;const p=project.value!,c=[...(modeCells.value||p.cells)],r=placement.value;if(moving.value)rectIndices(clipboard.value.rect,p.width).forEach(i=>c[i]=null);clipboard.value.cells.forEach((v,i)=>{if(v)c[(r.y+Math.floor(i/r.width))*p.width+r.x+i%r.width]=v});return c})
const placementCollision=computed(()=>{if(!placement.value||!clipboard.value)return 0;const source=moving.value?new Set(rectIndices(clipboard.value.rect,project.value!.width)):new Set<number>();return clipboard.value.cells.reduce((sum,c,i)=>{const j=(placement.value!.y+Math.floor(i/placement.value!.width))*project.value!.width+placement.value!.x+i%placement.value!.width;return sum+(c&&(modeCells.value||project.value!.cells)[j]&&!source.has(j)?1:0)},0)})
function place(index:number){if(!clipboard.value)return;const r=clipboard.value.rect;placement.value={...r,x:Math.min(index%project.value!.width,project.value!.width-r.width),y:Math.min(Math.floor(index/project.value!.width),project.value!.height-r.height)}}
function finishPlacement(){if(placementCells.value){stroke(placementCells.value);selected.value=null;placing.value=false;tool.value='select';placement.value=null}}
function editSelection(action:'fill'|'clear'|'mirror-x'|'mirror-y'){if(!selected.value)return;const r=selected.value,p=project.value!,source=modeCells.value||p.cells,cells=[...source];rectIndices(r,p.width).forEach(i=>{const x=i%p.width-r.x,y=Math.floor(i/p.width)-r.y;cells[i]=action==='fill'?(source[i]?color.value:null):action==='clear'?null:p.cells[(r.y+(action==='mirror-y'?r.height-1-y:y))*p.width+r.x+(action==='mirror-x'?r.width-1-x:x)]});stroke(cells);selected.value=null;tool.value='select'}
function dimensionInput(axis:'width'|'height',value:string){const n=Number(value);if(axis==='width')widthDraft.value=n;else heightDraft.value=n;if(ratioLocked.value&&n>0){if(axis==='width')heightDraft.value=Math.round(n*project.value!.height/project.value!.width);else widthDraft.value=Math.round(n*project.value!.width/project.value!.height)}}
async function applyResize(){const p=project.value!,w=Math.round(Number(widthDraft.value)),h=Math.round(Number(heightDraft.value));if(w<8||w>180||h<8||h>180||!Number.isFinite(w+h))return showToast('宽高请输入 8–180 格');const cells=resizeCells(p.cells,p.width,w,h,anchor.value),lost=total.value-cells.filter(Boolean).length;if(lost>0){try{await showConfirmDialog({className:'pin-confirm',theme:'round-button',confirmButtonColor:'var(--animal-primary)',title:'缩小画布',message:`将裁掉 ${lost} 颗，可撤销。`})}catch{return}}commit(cells,w,h);closePanel();await nextTick();board.value?.fit()}
async function clearAll(){try{await showConfirmDialog({className:'pin-confirm',theme:'round-button',confirmButtonColor:'var(--animal-primary)',title:'清空图纸？',message:'清空全部拼豆，可撤销。'});commit(Array(project.value!.cells.length).fill(null));closePanel();if(store.flush())showToast('已清空图纸')}catch{}}
function lock(){if(project.value)store.update({...project.value,layers:[{...layer.value!,locked:!layer.value?.locked}]})}
function toggleVisible(){if(project.value)store.update({...project.value,layers:[{...layer.value!,visible:!layer.value?.visible}]})}
function loadImage(url:string){generationId++;image.value=null;candidate.value=null;generationError.value='';imageUrl.value=url;generating.value=true;const img=new Image();img.onload=()=>{if(alive&&imageUrl.value===url){image.value=img;generating.value=false;resetPhotoHistory();if(mode.value!=='import'||importStage.value!=='photo')scheduleGeneration()}};img.onerror=()=>{if(alive&&imageUrl.value===url){generating.value=false;generationError.value='图片读取失败，请重新选择'}};img.src=url}
function adjustGenerated(page:string){adjustSource();singleImportPage.value=true;importPage.value=page}
function adjustSource(){if(!imageUrl.value)return;enterMode('import');importStage.value='photo';importPage.value='';loadImage(imageUrl.value)}
function importPhoto(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type))return showToast('请选择 PNG、JPG 或 WebP 图片');enterMode('import');imageType.value=null;targetWidth.value=Math.min(29,project.value!.width);maxColors.value=16;style.value='cartoon';cropRatio.value='free';rotation.value=0;crop.value={x:0,y:0,width:1,height:1};cropDraft.value={...crop.value};cropEditing.value=false;sourceBlob.value=file;imageName.value=file.name;importStage.value='photo';importPage.value='';category.value='draw';loadImage(URL.createObjectURL(file));input.value=''}
function scheduleGeneration(){clearTimeout(generationTimer);generationId++;generationError.value='';if(!image.value)return;generating.value=true;const id=generationId;generationTimer=setTimeout(()=>generate(id),320)}
function orientedPhoto(){const img=image.value;if(!img)return null;if(!rotation.value)return img;const canvas=document.createElement('canvas'),odd=rotation.value%180!==0;canvas.width=odd?img.naturalHeight:img.naturalWidth;canvas.height=odd?img.naturalWidth:img.naturalHeight;const ctx=canvas.getContext('2d')!;ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(rotation.value*Math.PI/180);ctx.drawImage(img,-img.naturalWidth/2,-img.naturalHeight/2);return canvas}
const processedPhoto=computed(()=>{const src=orientedPhoto();return src instanceof HTMLCanvasElement?src.toDataURL('image/png'):imageUrl.value})
function rotatePhoto(direction:number){const c=crop.value;crop.value=direction>0?{x:1-c.y-c.height,y:c.x,width:c.height,height:c.width}:{x:c.y,y:1-c.x-c.width,width:c.height,height:c.width};rotation.value=(rotation.value+direction*90+360)%360}
const generatedSize=computed(()=>{const img=image.value,p=project.value;if(!img||!p)return {width:1,height:1};const odd=rotation.value%180!==0;return fitImageToBoard((odd?img.naturalHeight:img.naturalWidth)*crop.value.width,(odd?img.naturalWidth:img.naturalHeight)*crop.value.height,p.width,p.height,targetWidth.value)});
const sizePresets=computed(()=>{const limit=Math.max(project.value!.width,project.value!.height);return (imageType.value==='photo'?[29,40,52]:[29,40,48]).filter(n=>n<=limit)})
function selectImageType(type:'cartoon'|'photo',page='detail'){
  imageType.value=type
  style.value=type==='cartoon'?'cartoon':'realistic'
  targetWidth.value=Math.min(type==='cartoon'?29:52,Math.max(project.value!.width,project.value!.height))
  maxColors.value=type==='cartoon'?16:32
  importPage.value=page
  resetPhotoHistory()
}
const croppedPhoto=computed(()=>{const src=orientedPhoto();if(!src||!image.value)return '';if(crop.value.x===0&&crop.value.y===0&&crop.value.width===1&&crop.value.height===1)return processedPhoto.value;const sw=src instanceof HTMLCanvasElement?src.width:image.value.naturalWidth,sh=src instanceof HTMLCanvasElement?src.height:image.value.naturalHeight,c=document.createElement('canvas');c.width=Math.max(1,Math.round(sw*crop.value.width));c.height=Math.max(1,Math.round(sh*crop.value.height));c.getContext('2d')!.drawImage(src,sw*crop.value.x,sh*crop.value.y,c.width,c.height,0,0,c.width,c.height);return c.toDataURL('image/png')})
function openCrop(){cropDraft.value={...crop.value};cropEditing.value=true}
function cancelCrop(){cropDraft.value={...crop.value};cropEditing.value=false}
function confirmCrop(){crop.value={...cropDraft.value};cropEditing.value=false;importPage.value='detail'}
function generate(id:number){if(!image.value)return;if(allowedMode.value&&!allowed.value.length){generationError.value='请至少选择一种允许使用的颜色';generating.value=false;return}try{const src=orientedPhoto()!,sw=src instanceof HTMLCanvasElement?src.width:image.value.naturalWidth,sh=src instanceof HTMLCanvasElement?src.height:image.value.naturalHeight;const dimensions=generatedSize.value,c=document.createElement('canvas');c.width=dimensions.width*3;c.height=dimensions.height*3;const ctx=c.getContext('2d')!;ctx.drawImage(src,sw*crop.value.x,sh*crop.value.y,sw*crop.value.width,sh*crop.value.height,0,0,c.width,c.height);const pixels=ctx.getImageData(0,0,c.width,c.height).data;worker?.terminate();worker=new Worker(new URL('../engine/generation.worker.ts',import.meta.url),{type:'module'});worker.onmessage=e=>{if(e.data.id!==generationId||!alive)return;generating.value=false;if(e.data.error)generationError.value=e.data.error;else {candidate.value={...dimensions,cells:e.data.cells};if(mode.value==='import'){importStage.value='preview';resetPhotoHistory();modeUndo.value=[];modeRedo.value=[];tool.value='pan'}}};worker.onerror=()=>{if(id===generationId){generating.value=false;generationError.value='生成失败，请重试'}};worker.postMessage({id,...dimensions,pixels,maxColors:maxColors.value,allowed:allowedMode.value?Array.from(allowed.value):[],style:style.value,removeBackground:removeBackground.value,tolerance:tolerance.value},[pixels.buffer])}catch{generating.value=false;generationError.value='无法处理这张图片，请重试或更换图片'}}
watch([targetWidth,maxColors,style,removeBackground,tolerance,allowedMode,allowed],()=>{if(image.value&&(mode.value!=='import'||importStage.value==='preview'))scheduleGeneration()},{deep:true})
function toggleAllowed(code:string){allowed.value=allowed.value.includes(code)?allowed.value.filter(c=>c!==code):[...allowed.value,code]}
async function applyGeneration(){if(!candidate.value||generating.value||generationError.value)return;const c=candidate.value,p=project.value!;if(!c.cells.some(Boolean)){showToast('图纸没有豆子，请调整后生成');return}if(p.cells.some(Boolean)){try{await showConfirmDialog({className:'pin-confirm',theme:'round-button',confirmButtonColor:'var(--animal-primary)',title:'应用新的生成结果',message:'将替换当前图纸与尺寸，原内容可通过撤销恢复。'})}catch{return}}importAccepted=true;commit(c.cells,c.width,c.height);exitMode();category.value='draw';await nextTick();board.value?.fit();if(store.flush())showToast('图纸已应用')}
async function exportFile(format:'pdf'|'png'|'json'|'xlsx'|'legacy'){exporting.value=true;const exportingProject=snapshot();try{await document.fonts.ready;const exporters=await import('../engine/export');if(format==='json'||format==='legacy')exporters.downloadJson(exportingProject,format==='legacy');else exporters.exportProject(exportingProject,format,author.value)}catch{showToast('导出失败，请重试')}finally{exporting.value=false}}
async function importJson(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.activeBrand==='MARD'){const map=(c:string|null)=>c?.startsWith('mard-')?c.slice(5).toUpperCase():c;raw.cells=raw.cells?.map(map);raw.layers=raw.layers?.map((l:object & {cells:Cells})=>({...l,type:'bead',cells:l.cells.map(map)}))}const imported=store.importProject(raw);await router.push(`/studio/${imported.id}`)}catch(e){showToast((e as Error).message||'文件无效，当前作品未改动')}input.value=''}
function importReference(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(reference.value&&reference.value!==referenceBackup.value.url)URL.revokeObjectURL(reference.value);reference.value=URL.createObjectURL(file);referenceVisible.value=true;if(mode.value!=='reference')enterMode('reference');input.value=''}
function rename(){const name=nameDraft.value.trim();if(name&&project.value){store.update({...project.value,name});closePanel();if(store.flush())showToast('名称已保存')}}
async function leave(){board.value?.cancel();if(!store.flush()){showToast('本地保存失败，请先导出 JSON 备份');panel.value='export';return}await router.push('/')}
watch(()=>route.params.id,id=>{store.open(String(id));history.value=[];future.value=[];clearTransient();nextTick(()=>board.value?.fit())})
onMounted(async()=>{window.addEventListener('blur',endPeek);window.addEventListener('blur',endCompare);if(!project.value){router.replace('/');return}if(layer.value?.locked||layer.value?.visible===false)store.update({...project.value,layers:[{...layer.value!,locked:false,visible:true}]});const savedRef=settings.value.reference;if(savedRef){reference.value=savedRef.url;referenceOpacity.value=savedRef.opacity;referenceScale.value=savedRef.scale;referenceX.value=savedRef.x;referenceY.value=savedRef.y}const url=sessionStorage.getItem(`pocket-pin:import:${project.value.id}`);if(url){sessionStorage.removeItem(`pocket-pin:import:${project.value.id}`);imageName.value=project.value.name;enterMode('import');importStage.value='photo';importPage.value='';try{sourceBlob.value=await (await fetch(url)).blob()}catch{}loadImage(url)}})
onUnmounted(()=>{if(project.value)store.discardEmptyDraft(project.value.id);window.removeEventListener('blur',endPeek);window.removeEventListener('blur',endCompare);endPeek();alive=false;generationId++;clearTimeout(generationTimer);worker?.terminate();if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);if(reference.value)URL.revokeObjectURL(reference.value);store.flush()})
</script>

<template>
<div v-if="project" class="pin-studio">
  <header class="pin-header">
    <van-button class="pin-icon-button" :aria-label="t('返回图纸空间')" @click="leave"><van-icon name="arrow-left"/></van-button>
    <van-button class="pin-project-name" @click="nameDraft=project.name;openPanel('rename')">{{ project.name }}</van-button>

    <van-button v-if="!mode&&!selected&&!placing&&(!panel||panel==='usage'||panel==='export')" class="pin-usage-trigger" :aria-expanded="panel==='usage'" @click="openPanel('usage')">{{ t('用量') }}<van-icon :name="panel==='usage'?'arrow-up':'arrow-down'"/></van-button>
    <van-button v-if="!mode&&!selected&&!placing&&(!panel||panel==='usage'||panel==='export')" class="pin-export-trigger" type="primary" @click="openPanel('export')"><span>{{ t('导出') }}</span></van-button>
  </header>
  <div class="pin-summary"><span>{{ t(display.width) }} × {{ t(display.height) }}{{ t(' 格 · ') }}{{ t(total) }}{{ t(' 颗 · ') }}{{ t(usage.length) }}{{ t(' 色') }}</span><span class="pin-context">{{ t(selected?`已选 ${selectedIds.length} 颗拼豆`:['pencil','eraser'].includes(tool)?canvasContext:'') }}</span></div>
  <main class="pin-workspace" :class="{'has-panel':panel&&!['usage','export','rename'].includes(panel),'panel-expanded':expanded}">

    <section class="pin-canvas-region">
      <bead-canvas ref="board" :width="display.width" :height="display.height" :cells="placementCells||display.cells" :tool="panel==='generate'||panel==='reduce'||panel==='recolor'?'pan':tool" :color="color" :grid="mode==='grid'?settingsDraft.grid:settings.grid" :coordinates="mode==='display'?settingsDraft.coordinates:settings.coordinates" :boards="mode==='display'?settingsDraft.boards:settings.boards" :codes="mode==='display'?settingsDraft.codes:settings.codes" :round="mode==='display'?settingsDraft.round:settings.round" :reference-editing="mode==='reference'" :bead-opacity="mode==='reference'?.45:1" :visible="mode==='reference'?referencePeek:layer?.visible" @reference-transform="referenceScale=$event.scale;referenceX=$event.x;referenceY=$event.y" :locked="effectiveLocked" :clean-selection="mode==='cropBeads'" :selection="placement||selected" :highlights="mode==='recolor'?recolorIndices:selectedIds" :reference="referenceVisible&&panel!=='generate'?reference:''" :reference-opacity="referenceOpacity" :reference-scale="referenceScale" :reference-x="referenceX" :reference-y="referenceY" @change="stroke" @pick="pick" @focus="focus" @select="selectBeads" @context="canvasContext=$event" @place="place" @busy="busy=$event"/>
      <div v-if="mode==='import'&&importStage!=='preview'" class="pin-import-photo"><img v-if="croppedPhoto" :src="croppedPhoto" :alt="t('剪裁后的画面')"/><span v-if="generating">{{ t(importStage==='photo'?'正在读取照片…':'正在生成图纸…') }}</span></div>
      <div v-if="(panel==='generate'||mode==='import')&&generating" class="pin-status" role="status">{{ t('正在生成预览…') }}</div>
      <div v-if="layer?.locked" class="pin-lock-note">{{ t('图纸已锁定') }}</div>
    <div class="pin-history pin-board-history"><van-button class="pin-icon-button" :aria-label="t('撤销')" :title="t('撤销')" :disabled="!(mode==='recolor'?recolorUndo.length:mode==='import'&&importStage==='photo'?photoUndo.length:mode?modeUndo.length:history.length)||busy||!!layer?.locked" @click="undo"><van-icon name="revoke"/></van-button><van-button class="pin-icon-button" :aria-label="t('重做')" :title="t('重做')" :disabled="!(mode==='recolor'?recolorRedo.length:mode==='import'&&importStage==='photo'?photoRedo.length:mode?modeRedo.length:future.length)||busy||!!layer?.locked" @click="redo"><van-icon name="replay"/></van-button></div><van-button v-if="mode==='reference'" class="pin-icon-button pin-peek" :aria-label="t('按住查看拼豆效果')" @pointerdown.prevent="referencePeek=true;($event.currentTarget as HTMLElement).setPointerCapture($event.pointerId)" @pointerup="endReferencePeek" @pointercancel="endReferencePeek" @lostpointercapture="endReferencePeek" @blur="endReferencePeek" @keydown.space.prevent="referencePeek=true" @keyup.space.prevent="endReferencePeek"><tool-glyph name="mirror"/></van-button><van-button v-if="mode==='recolor'&&focused>=0" class="pin-icon-button pin-peek pin-recolor-compare" :aria-label="t('按住查看原图')" :aria-pressed="compareOriginal" @pointerdown.prevent="startCompare" @pointerup="endCompare" @pointercancel="endCompare" @lostpointercapture="endCompare" @blur="endCompare" @contextmenu.prevent @keydown.space.prevent="compareOriginal=true" @keyup.space.prevent="endCompare" @keydown.enter.prevent="compareOriginal=true" @keyup.enter.prevent="endCompare"><tool-glyph name="mirror"/></van-button><van-button v-if="!mode&&!selected&&!placing&&!panel" class="pin-icon-button pin-peek" :aria-label="t('按住预览整体，松开恢复')" :title="t('按住预览整体，松开恢复')" :aria-pressed="peeking" @pointerdown.prevent="startPeek" @pointerup="endPeek" @pointercancel="endPeek" @lostpointercapture="endPeek" @contextmenu.prevent @keydown.space.prevent="peeking=true;board?.beginPreview()" @keyup.space.prevent="endPeek" @blur="endPeek"><van-icon name="eye-o"/></van-button>
    </section>
    <div v-if="['usage','export','rename'].includes(panel)" class="pin-usage-overlay" @click="closePanel"></div>
    <Transition name="pin-panel-motion"><aside v-if="panel" class="pin-panel" :class="{'pin-usage-dropdown':['usage','export'].includes(panel),'pin-rename-sheet':panel==='rename'}" :role="panel==='usage'?'dialog':undefined" :aria-label="panelTitle">
      <div class="pin-panel-heading" v-if="!['rename','usage','export'].includes(panel)"><h2>{{ t(panelTitle) }}</h2><van-button class="pin-expand" @click="expanded=!expanded">{{ t(expanded?'收起':'展开') }}</van-button><van-button v-if="panel!=='usage'" class="pin-icon-button" :aria-label="t('关闭面板')" @click="closePanel"><van-icon name="cross"/></van-button></div>
      <div class="pin-panel-content">
        <template v-if="panel==='colors'||panel==='recolor'">
          <template v-if="panel==='recolor'"><p>{{ t('原色 ') }}{{ t(project.cells[focused]) }}{{ t(' · 影响 ') }}{{ t(recolorIndices.length) }}{{ t(' 颗') }}</p><div class="pin-segments"><van-button v-for="option in [{id:'single',label:'单格'},{id:'connected',label:'相连同色'},{id:'all',label:'全图同色'}]" :key="option.id" :class="{chosen:recolorScope===option.id}" @click="recolorScope=option.id as typeof recolorScope">{{ t(option.label) }}</van-button></div><p>{{ t('目标色 ') }}{{ t(targetColor) }}{{ t('，画布中可预览换色效果。') }}</p><div class="pin-actions"><van-button @click="compareOriginal=!compareOriginal">{{ t(compareOriginal?'看换色结果':'看原图') }}</van-button><van-button type="primary" @click="applyRecolor">{{ t('应用换色') }}</van-button></div></template>
          <div class="pin-segments"><van-button v-for="tab in [{id:'used',label:'本图用色'},{id:'recent',label:'最近'},{id:'all',label:'全部'}]" :key="tab.id" :class="{chosen:paletteTab===tab.id}" @click="paletteTab=tab.id">{{ t(tab.label) }}</van-button></div>
          <van-field v-model="search" :placeholder="t('搜索色号或名称，例如 H7')" :aria-label="t('搜索色号')"/>
          <div class="pin-swatches"><van-button v-for="c in filteredPalette" :key="c.code" :aria-label="`${c.code} ${c.name}`" :aria-pressed="(panel==='recolor'?targetColor:color)===c.code" :class="{chosen:(panel==='recolor'?targetColor:color)===c.code}" @click="chooseColor(c.code)"><i :style="{'--bead-color':c.hex}"></i><b>{{ t(c.code) }}</b><small v-if="counts.has(c.code)">{{ t(counts.get(c.code)) }}{{ t(' 颗') }}</small></van-button></div><p v-if="!filteredPalette.length">{{ t('这里还没有颜色，试试全部色卡。') }}</p>
        </template>
        <template v-if="panel==='generate'">
          <div class="pin-source"><img v-if="imageUrl" :src="imageUrl" alt="完整原图"><div><b>{{ t(imageName||'选择一张照片') }}</b><van-button @click="fileInput?.click()">{{ t(imageUrl?'更换图片':'选择图片') }}</van-button></div></div>
          <van-field :model-value="targetWidth" type="digit" :label="t('目标宽度')" right-icon="" @update:model-value="targetWidth=Math.max(8,Math.min(180,Number($event)||8))"/><p>{{ t('保持原图比例，最长边不超过 180 格。') }}</p>
          <div class="pin-segments"><van-button v-for="n in [26,52,78,104,156]" :key="n" :class="{chosen:targetWidth===n}" @click="targetWidth=n">{{ t(n) }}{{ t(' 格') }}</van-button></div>
          <label class="pin-range">{{ t('最多 ') }}{{ t(maxColors) }}{{ t(' 色') }}<van-slider v-model="maxColors" :min="2" :max="48" :step="1" :aria-label="t('生成色数上限')"/></label><div class="pin-segments"><van-button v-for="n in [8,12,16,24,32]" :key="n" :class="{chosen:maxColors===n}" @click="maxColors=n">{{ t(n) }}{{ t(' 色') }}</van-button></div>
          <div class="pin-segments"><van-button :class="{chosen:style==='cartoon'}" @click="style='cartoon'">{{ t('色块优先') }}</van-button><van-button :class="{chosen:style==='realistic'}" @click="style='realistic'">{{ t('自然还原') }}</van-button></div>
          <div class="pin-setting"><span>{{ t('去除近似背景色') }}</span><van-switch v-model="removeBackground" size="24px" :aria-label="t('去除背景')"/></div><label v-if="removeBackground" class="pin-range">{{ t('背景容差 ') }}{{ t(tolerance) }}<van-slider v-model="tolerance" :min="0" :max="120"/></label>
          <div class="pin-setting"><span>{{ t('只用我选择的色号') }}</span><van-switch v-model="allowedMode" size="24px" :aria-label="t('自选可用色号')"/></div>
          <template v-if="allowedMode"><p>{{ t('已选择 ') }}{{ t(allowed.length) }}{{ t(' 色') }}</p><div class="pin-actions"><van-button @click="allowed=usage.map(c=>c.code)">{{ t('使用本图颜色') }}</van-button><van-button @click="allowed=[]">{{ t('清除选择') }}</van-button></div><van-field v-model="allowedSearch" :placeholder="t('搜索允许使用的色号')"/><div class="pin-swatches pin-allowed"><van-button v-for="c in allowedPalette" :key="c.code" :class="{chosen:allowed.includes(c.code)}" :aria-pressed="allowed.includes(c.code)" @click="toggleAllowed(c.code)"><i :style="{'--bead-color':c.hex}"></i>{{ t(c.code) }}</van-button></div></template>
          <p v-if="generationError" role="alert">{{ t(generationError) }} <van-button @click="scheduleGeneration">{{ t('重试') }}</van-button></p>
          <div v-if="candidate" class="pin-result"><b>{{ t(candidate.width) }} × {{ t(candidate.height) }}{{ t(' 格') }}</b><span>{{ t('上限 ') }}{{ t(maxColors) }}{{ t(' 色 · 实际 ') }}{{ t(new Set(candidate.cells.filter(Boolean)).size) }}{{ t(' 色') }}</span></div>
          <van-button type="primary" block :disabled="!candidate||generating||!!generationError||!!layer?.locked" :loading="generating" @click="applyGeneration">{{ t(total?'应用到图纸':'开始编辑') }}</van-button><p>{{ t('预览不会修改当前作品，应用后才保存。') }}</p>
        </template>
        <template v-if="panel==='settings'">
          <h3>{{ t('图纸大小') }}</h3><div class="pin-dimensions"><van-field :model-value="widthDraft" type="digit" :label="t('宽')" @update:model-value="dimensionInput('width',$event)"/><van-field :model-value="heightDraft" type="digit" :label="t('高')" @update:model-value="dimensionInput('height',$event)"/></div>
          <div class="pin-setting"><span>{{ t('锁定当前宽高比') }}</span><van-switch v-model="ratioLocked" size="24px"/></div><div class="pin-segments"><van-button v-for="n in [52,78,104,156]" :key="n" @click="widthDraft=heightDraft=n">{{ t(n) }} × {{ t(n) }}</van-button></div>
          <div class="pin-segments"><van-button :class="{chosen:anchor==='center'}" @click="anchor='center'">{{ t('居中保留') }}</van-button><van-button :class="{chosen:anchor==='top-left'}" @click="anchor='top-left'">{{ t('左上对齐') }}</van-button></div><van-button :disabled="!!layer?.locked" @click="applyResize">{{ t('应用尺寸') }}</van-button>
          <h3>{{ t('画布显示') }}</h3><p>{{ t('缩小看轮廓，放大看格子。') }}</p><div class="pin-segments"><van-button v-for="o in [{id:'auto',label:'自动网格'},{id:'off',label:'关闭'},{id:'always',label:'始终显示'}]" :key="o.id" :class="{chosen:settings.grid===o.id}" @click="setSetting('grid',o.id)">{{ t(o.label) }}</van-button></div>
          <div v-for="o in [{id:'coordinates',label:'边缘坐标'},{id:'boards',label:'52 格拼豆板边界'},{id:'codes',label:'放大时显示色号'},{id:'round',label:'放大时显示圆豆'}]" :key="o.id" class="pin-setting"><span>{{ t(o.label) }}</span><van-switch :model-value="settings[o.id as keyof typeof settings] as boolean" size="24px" @update:model-value="setSetting(o.id,$event)"/></div>
          <div class="pin-setting"><span>{{ t('锁定图纸') }}</span><van-switch :model-value="!!layer?.locked" size="24px" @update:model-value="lock"/></div><div class="pin-setting"><span>{{ t('显示拼豆') }}</span><van-switch :model-value="layer?.visible!==false" size="24px" @update:model-value="toggleVisible"/></div>
          <div class="pin-actions"><van-button @click="openPanel('reference')">{{ t('参考照片') }}</van-button><van-button @click="openPanel('reduce')">{{ t('减少用色') }}</van-button></div><van-button type="danger" :disabled="!!layer?.locked||!total" @click="clearAll">{{ t('清空图纸') }}</van-button>
        </template>
        <template v-if="panel==='reduce'"><p>{{ t('保留主要颜色，将其他颜色合并到相近色。可以保护眼睛、描边等关键色。') }}</p><label class="pin-range">{{ t('最多 ') }}{{ t(reduceLimit) }}{{ t(' 色') }}<van-slider v-model="reduceLimit" :min="1" :max="Math.max(2,usage.length)" @update:model-value="reduced=null"/></label><div class="pin-swatches"><van-button v-for="c in usage" :key="c.code" :class="{chosen:protectedCodes.includes(c.code)}" :aria-pressed="protectedCodes.includes(c.code)" @click="toggleProtected(c.code)"><i :style="{'--bead-color':c.hex}"></i>{{ t(c.code) }}<small>{{ t(protectedCodes.includes(c.code)?'已保护':'保护此色') }}</small></van-button></div><van-button :disabled="!total||!!layer?.locked" @click="startReduction">{{ t('预览减少用色') }}</van-button><template v-if="reduced"><p>{{ t(usage.length) }}{{ t(' 色 → ') }}{{ t(new Set(reduced.filter(Boolean)).size) }}{{ t(' 色') }}</p><div class="pin-actions"><van-button @click="compareOriginal=!compareOriginal">{{ t(compareOriginal?'看处理结果':'看原图') }}</van-button><van-button type="primary" @click="commit(reduced);closePanel()">{{ t('应用') }}</van-button></div></template></template>
        <template v-if="panel==='reference'"><p>{{ t('照片仅用于当前会话，不计入拼豆材料或导出图纸。') }}</p><van-button @click="refInput?.click()">{{ t('选择参考照片') }}</van-button><template v-if="reference"><div class="pin-setting"><span>{{ t('显示参考图') }}</span><van-switch v-model="referenceVisible" size="24px"/></div><label class="pin-range">{{ t('透明度 ') }}{{ t(Math.round(referenceOpacity*100)) }}%<van-slider v-model="referenceOpacity" :min="0" :max="1" :step=".01"/></label><label class="pin-range">{{ t('缩放 ') }}{{ t(referenceScale.toFixed(1)) }}{{ t(' 倍') }}<van-slider v-model="referenceScale" :min=".1" :max="3" :step=".1"/></label><van-field v-model.number="referenceX" type="number" :label="t('横向偏移格数')"/><van-field v-model.number="referenceY" type="number" :label="t('纵向偏移格数')"/><van-button @click="referenceScale=1;referenceX=referenceY=0">{{ t('重置位置') }}</van-button></template></template>
        <template v-if="panel==='usage'"><div class="pin-usage-summary"><b>{{ t(total) }}{{ t(' 颗 · ') }}{{ t(usage.length) }}{{ t(' 色') }}</b><label><input :aria-label="t('每包颗数')" type="number" min="1" max="10000" :value="settings.beadsPerPack" @change="setSetting('beadsPerPack',Math.max(1,Math.min(10000,Number(($event.target as HTMLInputElement).value)||1)))"/>{{ t(' 颗/包 · 预计 ') }}{{ t(usage.reduce((s,c)=>s+Math.ceil(counts.get(c.code)!/settings.beadsPerPack),0)) }}{{ t(' 包') }}</label></div><div class="pin-usage"><div v-for="c in usage" :key="c.code"><i :style="{'--bead-color':c.hex}"></i><b>{{ t(c.code) }}</b><span>{{ t(counts.get(c.code)) }}{{ t(' 颗') }}</span><span>{{ t(Math.ceil(counts.get(c.code)!/settings.beadsPerPack)) }}{{ t(' 包') }}</span></div></div></template>
        <template v-if="panel==='export'"><div class="pin-studio-export"><export-panel :project="project"/></div></template>
        <template v-if="panel==='rename'"><van-field v-model="nameDraft" :placeholder="t('给作品起个名字')" maxlength="60" :aria-label="t('作品名称')" @keydown.enter="rename"/><div class="pin-operation-footer"><van-button class="pin-icon-button" :aria-label="t('取消改名')" @click="closePanel"><van-icon name="cross"/></van-button><b>{{ t('作品名称') }}</b><van-button class="pin-icon-button" :aria-label="t('保存名称')" :disabled="!nameDraft.trim()" @click="rename"><van-icon name="success"/></van-button></div></template>
      </div>
    </aside></Transition>
  </main>
