    <div class="pin-operation-footer"><van-button class="pin-icon-button" :aria-label="t('返回上一层')" @click="placing?(placing=false,placement=null,tool='select'):selected=null"><van-icon name="arrow-left"/></van-button><b>{{ t(placing?(moving?'移动拼豆':'复制拼豆'):'选区编辑') }}</b><van-button class="pin-icon-button" :aria-label="t('确认操作')" :disabled="placing&&(!placement||placementCollision>0)" @click="placing?finishPlacement():selected=null"><van-icon name="success"/></van-button></div>
  </div>
