    <nav v-drag-scroll class="pin-tools" :aria-label="t('编辑工具')"><van-button v-for="item in tools" :key="item.id" :class="{chosen:tool===item.id}" :aria-pressed="tool===item.id" :disabled="!!layer?.locked&&!['pan','eyedropper'].includes(item.id)" @click="activate(item.id)"><tool-glyph :name="item.id==='select'?'copy':item.id"/><span>{{ t(item.label) }}</span></van-button></nav>  </div>
