  <nav v-if="category==='import'&&!mode" class="pin-edit-menu pin-import-menu" :aria-label="t('导入图片')"><van-button class="pin-empty-import" :aria-label="t('选择图片')" @click="fileInput?.click()"><tool-glyph name="import"/><span>{{t('选择图片')}}</span></van-button></nav>
  <footer v-if="!selected&&!placing&&!mode" class="pin-categories" :aria-label="t('功能分类')"><van-button v-for="item in [{id:'draw',name:'绘图'},{id:'import',name:'导入'},{id:'edit',name:'编辑'}]" :key="item.id" :class="{chosen:category===item.id}" :aria-pressed="category===item.id" @click="changeCategory(item.id)">{{ t(item.name) }}</van-button></footer>
