    <div class="pin-mode-controls">
      <template v-if="['pencil','fill','eraser'].includes(mode)"><p>{{ t(tool==='eyedropper'?'点击豆板上的豆子取色':mode==='fill'?'拖出矩形，松手填充':tool==='eraser'?'拖动擦除豆子':'单指画豆子，双指缩放与移动') }}</p><color-dock v-if="mode!=='eraser'" :color="color" :can-pick="true" :can-erase="mode==='pencil'" :erasing="tool==='eraser'" @erase="tool=tool==='eraser'?'pencil':'eraser'" @choose="chooseColor" @pick="tool='eyedropper'"/></template>
