        <template v-else><p>{{ t(project.cells[focused]) }} → {{ t(targetColor) }} · {{ t(recolorIndices.length) }}{{ t(' 颗') }}</p><color-dock :key="focused" :color="targetColor" :can-pick="false" :recommended="suggested" default-recommended @choose="chooseColor"/>
        <div v-drag-scroll class="pin-recolor-scope" :aria-label="t('替换范围')"><van-button v-for="o in [{id:'single',name:'单颗'},{id:'connected',name:'相连'},{id:'all',name:'全图同色'}]" :key="o.id" :class="{chosen:recolorScope===o.id}" @click="recolorScope=o.id as typeof recolorScope">{{ t(o.name) }}</van-button></div></template>
      </div>
