      <nav v-if="mode==='mirror'" class="pin-tools pin-mirror-menu" :aria-label="t('镜像操作')"><van-button :aria-label="t('水平镜像')" @click="mirror('x')"><tool-glyph name="mirror"/><span>{{ t('水平镜像') }}</span></van-button><van-button :aria-label="t('垂直镜像')" @click="mirror('y')"><tool-glyph name="mirror" class="pin-mirror-vertical"/><span>{{ t('垂直镜像') }}</span></van-button></nav>
