      <div v-if="mode==='reference'" class="pin-reference-editor"><label v-if="editStep==='opacity'&&reference" class="pin-range">{{t('透明度')}}<van-slider v-model="referenceOpacity" :min="0" :max="1" :step=".01"/></label><div class="pin-mode-options"><van-button class="pin-reference-photo pin-empty-import" @click="refInput?.click()"><img v-if="reference" :src="reference"/><tool-glyph v-else name="import"/><span>{{t(reference?'选择图片':'导入图片')}}</span></van-button><van-button v-if="reference" :class="{chosen:editStep==='opacity'}" @click="editStep=editStep==='opacity'?'photo':'opacity'">{{t('透明度')}}</van-button></div><p>{{t('拖动图片，双指缩放；确认后保存')}}</p></div>
