            </div>
            <div v-if="importPage==='rotate'" class="pin-import-control"><div class="pin-mode-options"><van-button @click="rotatePhoto(-1)"><van-icon name="revoke"/>{{ t('逆时针') }}</van-button><van-button @click="rotatePhoto(1)"><van-icon name="replay"/>{{ t('顺时针') }}</van-button></div></div>
            <div v-if="importPage==='detail'" class="pin-import-control"><label class="pin-range">{{ t('图案大小') }} · {{ generatedSize.width }} × {{ generatedSize.height }} {{ t('格') }}<van-slider v-model="targetWidth" :min="Math.min(8,Math.max(project.width,project.height))" :max="Math.max(project.width,project.height)" :step="1"/></label><div class="pin-segments pin-size-presets"><van-button v-for="n in sizePresets" :key="n" :class="{chosen:targetWidth===n}" @click="targetWidth=n">{{ n }}{{ t(' 格') }}</van-button><van-button v-if="Math.max(project.width,project.height)>sizePresets.at(-1)!" @click="targetWidth=Math.max(project.width,project.height)">{{ t('最大') }}</van-button></div><p>{{ t(imageType==='cartoon'?'默认小尺寸，可继续调整':'默认 52 格，保持原图比例') }}</p></div>
            <div v-if="importPage==='colors'" class="pin-import-control"><label class="pin-range">{{ t('用色上限') }} · {{ maxColors }} {{ t('色') }}<van-slider v-model="maxColors" :min="2" :max="211"/></label></div>
            <div v-if="importPage==='style'" class="pin-import-control"><div class="pin-mode-options"><van-button :class="{chosen:imageType==='cartoon'}" @click="selectImageType('cartoon','style')">{{ t('卡通／插画') }}</van-button><van-button :class="{chosen:imageType==='photo'}" @click="selectImageType('photo','style')">{{ t('照片／写实') }}</van-button></div><p>{{ t(imageType==='cartoon'?'保留轮廓、表情和清晰色块':'保留明暗、质感和空间层次') }}</p></div>
