            <div v-if="importPage==='palette'" class="pin-import-control"><div class="pin-mode-options"><van-button :class="{chosen:!allowedMode}" @click="allowedMode=false">{{ t('全部 211 色') }}</van-button><van-button :class="{chosen:allowedMode}" @click="allowedMode=true;importPaletteOpen=true">{{ t('只用我有的颜色') }}</van-button></div><van-button v-if="allowedMode" @click="importPaletteOpen=true">{{ t('已选') }} {{ allowed.length }} {{ t('色 · 点击修改') }}</van-button><p v-else>{{ t('自动从完整色卡匹配最接近的颜色') }}</p></div>
