          </template>
        </div>
        <nav v-if="!singleImportPage&&imageType" v-drag-scroll class="pin-tools pin-parameter-menu" :aria-label="t('导入照片功能')"><van-button v-for="o in [{id:'size',name:'裁剪',icon:'expand-o'},{id:'rotate',name:'旋转',icon:'replay'},{id:'detail',name:'图案大小',icon:'apps-o'},{id:'colors',name:'色数',icon:'brush-o'},{id:'style',name:'图片类型',icon:'photo-o'},{id:'background',name:'背景',icon:'filter-o'},{id:'palette',name:'我的豆色',icon:'apps-o'},...(importStage==='preview'?[{id:'retouch',name:'修整豆子',icon:'edit'},{id:'preview',name:'整体预览',icon:'eye-o'}]:[])]" :key="o.id" :class="{chosen:importPage===o.id,'was-edited':photoChanged(o.id)}" :disabled="importStage==='generating'" @click="importPage=o.id;tool='pan';if(o.id==='size')openCrop();if(o.id==='size'||o.id==='rotate')importStage='photo'"><van-icon :name="o.icon"/><span>{{ t(o.name) }}</span></van-button></nav>
