      <p v-if="mode==='clear'">{{ t('清空全部拼豆，保留豆板尺寸。确认后可撤销。') }}</p>
    </div>
    <div class="pin-operation-footer"><van-button class="pin-icon-button" :aria-label="t('取消当前操作')" @click="exitMode"><van-icon name="cross"/></van-button><b>{{ t(modeTitle) }}</b><van-button class="pin-icon-button" :class="{'pin-generate-action':mode==='import'&&importStage!=='preview'}" :title="mode==='import'?(importStage==='preview'?'确认应用到豆板':'生成图纸预览'):'保存'" :aria-label="t('保存当前操作')" :disabled="mode==='importPlace'&&(!placement||placementCollision>0)||mode==='recolor'&&focused<0||busy||mode==='import'&&(generating||!image||!imageType||!!generationError||importStage==='preview'&&!!layer?.locked||allowedMode&&!allowed.length)" @click="saveMode"><span v-if="mode==='import'&&importStage!=='preview'">{{ t(generating?'正在生成':'生成图纸') }}</span><van-icon v-else name="success"/></van-button></div>
  </section></Transition>
  <div v-if="cropEditing" class="pin-crop-overlay" role="dialog" :aria-label="t('剪裁照片')"><div class="pin-crop-stage"><photo-crop v-if="imageUrl" v-model="cropDraft" :src="processedPhoto" :square="cropRatio==='square'" active/></div><div class="pin-crop-sheet"><div class="pin-mode-options"><van-button :class="{chosen:cropRatio==='free'}" @click="cropRatio='free'">{{t('自由')}}</van-button><van-button :class="{chosen:cropRatio==='square'}" @click="cropRatio='square'">1:1</van-button></div><div class="pin-operation-footer"><van-button class="pin-icon-button" :aria-label="t('取消剪裁')" @click="cancelCrop"><van-icon name="cross"/></van-button><b>{{ t('剪裁照片') }}</b><van-button class="pin-icon-button" :aria-label="t('确认剪裁')" @click="confirmCrop"><van-icon name="success"/></van-button></div></div></div>
  <div v-if="importPaletteOpen" class="pin-import-palette-overlay" @click.self="importPaletteOpen=false"><section class="pin-palette-sheet" role="dialog" :aria-label="t('导入色号')"><div class="pin-panel-heading"><h2>{{ t(importPage==='retouch'?'修整颜色':'允许使用的色号') }}</h2><van-button class="pin-icon-button" :aria-label="t('关闭导入色卡')" @click="importPaletteOpen=false"><van-icon name="cross"/></van-button></div><van-field v-model="allowedSearch" :placeholder="t('搜索色号')"/><div class="pin-swatches"><van-button v-for="c in allowedPalette" :key="c.code" :class="{chosen:importPage==='retouch'?color===c.code:allowed.includes(c.code)}" @click="importPage==='retouch'?chooseColor(c.code):toggleAllowed(c.code)"><i :style="{'--bead-color':c.hex}"></i><b>{{ t(c.code) }}</b></van-button></div></section></div>
  <input ref="fileInput" hidden type="file" accept="image/png,image/jpeg,image/webp" @change="importPhoto"><input ref="jsonInput" hidden type="file" accept="application/json,.json" @change="importJson"><input ref="refInput" hidden type="file" accept="image/png,image/jpeg,image/webp" @change="importReference">
</div>
</template>
